import { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { FieldProps } from 'components/Filter/types';
import {
  MultiValueRemove,
  StyledChips,
} from 'components/Form/components/Select/Select.styles';
import { ChevronDown, ChevronUp, Close, Icon } from 'components/icon';
import { Popover } from 'components/Popover';
import { Button } from 'components/UI';
import { usesPerformanceToolTimePeriod } from 'domain/Filter';
import { usePageFilterData } from 'hooks';
import type { Option } from 'models/Filters';
import {
  PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT,
  PERFORMANCE_TOOL_PAGE_NAME,
} from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import { getPerformanceToolVolumeTimePeriodDisplaySelection } from 'pages/pillars/ValueCreation/PerformanceTool/utils/getPerformanceToolVolumeTimePeriodDisplaySelection';
import { selectPage } from 'redux/slices/filters/selectors';
import {
  formatTimePeriodLabel as buildTimePeriodLabel,
  getClosedYear,
  resolveTimePeriodSelection,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import {
  TimePeriodSelection,
  TimePeriodSelector,
} from '../../../TimePeriodSelector';
import { ResetFilterButton } from './ResetFilterButton';
import {
  FooterActions,
  TriggerButton,
  TriggerChipValue,
  TriggerIcon,
  TriggerLabel,
  TriggerValueContainer,
} from './TimePeriodQuickFilter.styles';

export const TimePeriodQuickFilter = ({
  dataTestId,
  pageName,
  onValuesChange,
  getCurrentValue,
}: FieldProps) => {
  const { dataFilters } = usePageFilterData(pageName);
  const timePeriod = dataFilters?.time_period;
  const periodTypes = timePeriod?.values as Option[] | undefined;
  const maxDtEnd = timePeriod?.max_dt_end;
  const defaultSelection = resolveTimePeriodSelection(
    timePeriod?.default?.value,
    timePeriod?.default_dt_end,
    maxDtEnd,
  );
  const currentType = getCurrentValue('period_type');
  const currentDtEnd = getCurrentValue('dt_end');
  const pageState = useSelector(selectPage(pageName));
  const usesTimePeriod = usesPerformanceToolTimePeriod(dataFilters);
  const volumeChartPeriodType = usesTimePeriod
    ? pageState?.performanceToolVolumeChartPeriodType
    : null;

  const appliedSelection =
    resolveTimePeriodSelection(currentType, currentDtEnd, maxDtEnd) ??
    defaultSelection;

  const displaySelection =
    getPerformanceToolVolumeTimePeriodDisplaySelection({
      volumeChartPeriodType,
      dtEnd: currentDtEnd,
      cutoffDate: maxDtEnd,
    }) ?? appliedSelection;

  const [draftSelection, setDraftSelection] =
    useState<TimePeriodSelection | null>(displaySelection);
  const openPopoverRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (pageName !== PERFORMANCE_TOOL_PAGE_NAME) {
      return;
    }

    const handleOpenTimePeriod = () => {
      openPopoverRef.current?.();
    };

    globalThis.addEventListener(
      PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT,
      handleOpenTimePeriod,
    );

    return () => {
      globalThis.removeEventListener(
        PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT,
        handleOpenTimePeriod,
      );
    };
  }, [pageName]);

  if (
    !timePeriod?.enabled ||
    !periodTypes?.length ||
    !maxDtEnd ||
    !defaultSelection ||
    !appliedSelection ||
    !displaySelection ||
    !onValuesChange
  ) {
    return null;
  }

  const displayYear =
    displaySelection.periodType === TimePeriodType.FY
      ? Number(displaySelection.dtEnd.slice(0, 4))
      : getClosedYear(maxDtEnd);

  const displayValue = buildTimePeriodLabel(
    displaySelection.periodType,
    displaySelection.end,
    displayYear,
  );

  const showClearIcon =
    appliedSelection.periodType !== defaultSelection.periodType ||
    appliedSelection.dtEnd !== defaultSelection.dtEnd;

  const emitValuesChange = (selection: TimePeriodSelection) => {
    onValuesChange({
      period_type: selection.periodType,
      dt_end: selection.dtEnd,
    });
  };

  const handleClear = () => {
    emitValuesChange(defaultSelection);
  };

  return (
    <Popover
      dataTestId={dataTestId ? `${dataTestId}-time-period-popover` : undefined}
      onOpen={() => setDraftSelection(displaySelection)}
      renderTrigger={({
        triggerRef,
        isOpen,
        open,
        close,
        onTriggerKeyDown,
      }) => {
        openPopoverRef.current = open;

        return (
          <TriggerButton
            data-testid={dataTestId ? `${dataTestId}-time-period` : undefined}
            ref={triggerRef}
            role="button"
            tabIndex={0}
            aria-haspopup="dialog"
            aria-expanded={isOpen}
            onClick={isOpen ? close : open}
            onKeyDown={onTriggerKeyDown}
          >
            <TriggerValueContainer
              data-testid={
                dataTestId
                  ? `${dataTestId}-time-period-value-container`
                  : undefined
              }
            >
              <TriggerLabel>Time Frame</TriggerLabel>
              <StyledChips
                $size="medium"
                data-testid={
                  dataTestId ? `${dataTestId}-time-period-chip` : undefined
                }
              >
                <TriggerChipValue
                  data-testid={
                    dataTestId
                      ? `${dataTestId}-time-period-chip-value`
                      : undefined
                  }
                >
                  {displayValue}
                </TriggerChipValue>
                {showClearIcon && (
                  <MultiValueRemove
                    as="button"
                    data-testid={
                      dataTestId ? `${dataTestId}-time-period-clear` : undefined
                    }
                    aria-label="Clear Time Period"
                    onClick={(event) => {
                      event.stopPropagation();
                      handleClear();
                      close();
                    }}
                    onMouseDown={(event) => {
                      event.preventDefault();
                      event.stopPropagation();
                    }}
                    style={{ border: 0, cursor: 'pointer', padding: 0 }}
                  >
                    <Icon icon={Close} size="small" color="#141414" />
                  </MultiValueRemove>
                )}
              </StyledChips>
            </TriggerValueContainer>
            <TriggerIcon aria-hidden="true">
              <Icon
                icon={ChevronDown}
                style={{ display: isOpen ? 'none' : 'flex' }}
                data-testid={
                  dataTestId ? `${dataTestId}-caret-down` : undefined
                }
              />
              <Icon
                icon={ChevronUp}
                style={{ display: isOpen ? 'flex' : 'none' }}
                data-testid={dataTestId ? `${dataTestId}-caret-up` : undefined}
              />
            </TriggerIcon>
          </TriggerButton>
        );
      }}
    >
      {({ close }) => (
        <TimePeriodSelector
          periodTypes={periodTypes}
          maxDtEnd={maxDtEnd}
          selectedType={
            draftSelection?.periodType ?? displaySelection.periodType
          }
          selectedDtEnd={draftSelection?.dtEnd ?? displaySelection.dtEnd}
          onChange={setDraftSelection}
          footer={
            <FooterActions>
              <ResetFilterButton
                dataTestId={
                  dataTestId ? `${dataTestId}-time-period` : undefined
                }
                onResetFilter={() => setDraftSelection(defaultSelection)}
              />
              <Button
                data-testid={
                  dataTestId ? `${dataTestId}-time-period-apply` : undefined
                }
                size="medium"
                variant="primary"
                type="button"
                onClick={() => {
                  emitValuesChange(draftSelection ?? displaySelection);
                  close();
                }}
              >
                Apply
              </Button>
            </FooterActions>
          }
        />
      )}
    </Popover>
  );
};
